 495	/// Ecosystems whose publish gets confirmed against the registry before the
 496	/// operation is marked done. Npm and Cargo are checked; PyPI has the
 497	/// identical propagation-lag gap, deliberately deferred -- no PyPI package
 498	/// or credentials in this workspace to test a fix against. The single
 499	/// source of truth `dispatch_registry` actually consults, so a test on this
 500	/// function directly proves the runtime gate, not a copy of it.
 501	fn ecosystem_requires_registry_confirmation(ecosystem: Ecosystem) -> bool {
 502	    matches!(ecosystem, Ecosystem::Npm | Ecosystem::Cargo)
 503	}
 504	
 505	/// A successful publish-client exit isn't a receipt: confirms the registry
 506	/// itself has caught up before treating the operation as done. If not, it
 507	/// stays `Attempting` for reconciliation, reported via its own variant
 508	/// rather than `ReleaseIntentStale`'s false "no operation was authorized".
 509	fn require_registry_confirmation(is_published: bool, package: &str, version: &Version) -> Result<(), GraphError> {
 510	    if is_published {
 511	        return Ok(());
 512	    }
 513	    Err(GraphError::RegistryPublishUnconfirmed {
 514	        package: package.to_string(),
 515	        version: version.clone(),
 516	    })
 517	}
 518	
 519	/// Retries after this many unconfirmed checks: 3 retries (4 checks total).
 520	const REGISTRY_CONFIRMATION_MAX_RETRIES: u32 = 3;
 521	
 522	/// Exponential backoff between confirmation checks: 2s, 4s, 8s (14s worst
 523	/// case) -- registry index propagation is normally sub-second, so this only
 524	/// costs time on the rare lagging case, not the common one.
 525	fn registry_confirmation_backoff(retry: u32) -> std::time::Duration {
 526	    std::time::Duration::from_secs(2u64.pow(retry + 1))
 527	}
 528	
 529	/// Retries `check` up to `max_retries` more times, sleeping `backoff(retry)`
 530	/// between attempts, and returns as soon as it reports published. Returns
 531	/// `Ok(false)` if it never does. `sleep` is injected so tests can verify the
 532	/// retry count and schedule without a real wall-clock wait.
 533	fn poll_until_published(
 534	    mut check: impl FnMut() -> Result<bool, GraphError>,
 535	    max_retries: u32,
 536	    backoff: impl Fn(u32) -> std::time::Duration,
 537	    sleep: impl Fn(std::time::Duration),
 538	) -> Result<bool, GraphError> {
 539	    for retry in 0..=max_retries {
 540	        if check()? {
 541	            return Ok(true);
 542	        }
 543	        if retry < max_retries {
 544	            sleep(backoff(retry));
 545	        }
 546	    }
 547	    Ok(false)
 548	}
