 550	impl ValidatedReleaseIntent<'_> {
 551	    /// Runs a [`registry_argv::Argv`] built by the pure argv layer. This is
 552	    /// the only place `dispatch_registry` touches [`CommandRunner`] --
 553	    /// everything about *what* to run (program, args, cwd) was already
 554	    /// decided by `registry_argv`.
 555	    fn run_argv(&self, argv: &registry_argv::Argv) -> Result<CommandOutput, GraphError> {
 556	        let args: Vec<&str> = argv.args.iter().map(String::as_str).collect();
 557	        Ok(self.runner.run(&argv.program, &args, &argv.cwd)?)
 558	    }
