 596	        &self,
 597	        package_name: &str,
 598	        version: &Version,
 599	        registry_key: Option<&str>,
 600	    ) -> Result<bool, GraphError> {
 601	        let spec = format!("{package_name}@{}", version.render());
 602	        let mut args = vec!["info", spec.as_str()];
 603	        if let Some(registry) = registry_key {
 604	            args.extend(["--registry", registry]);
 605	        }
 606	        let output = self
 607	            .runner
 608	            .run_quiet("cargo", &args, &self.prepared.root, std::time::Duration::from_secs(300))?;
 609	        registry_argv::classify_cargo_info_output(&output).map_err(|source| GraphError::Registry {
 610	            package: package_name.to_string(),
 611	            source,
 612	        })
 613	    }
