 670	    fn dispatch_forge_release(&self, tag: &TagName) -> Result<OperationOutcome, GraphError> {
 671	        let remote = self.checked_git_remote()?;
 672	        let repository = remote
 673	            .github_repository
 674	            .as_ref()
 675	            .ok_or(GraphError::ReleasePreconditionUnmet {
 676	                requirement: ReleasePreconditionRequirement::GitHubRemote,
 677	            })?
 678	            .as_slug();
 679	        match self.observed_forge_release_target(tag, &repository)? {
 680	            ForgeReleaseObservation::Exact => return Ok(OperationOutcome::AlreadySatisfied),
 681	            ForgeReleaseObservation::Conflict => {
 682	                return Err(GraphError::ReleaseRemoteConflict {
 683	                    conflict: RemoteConflict::ForgeReleaseDiffers,
 684	                })
 685	            }
 686	            ForgeReleaseObservation::Missing => {}
 687	        }
 688	        let create_args = [
 689	            "release",
 690	            "create",
 691	            tag.as_str(),
 692	            "--repo",
 693	            repository.as_str(),
 694	            "--verify-tag",
 695	            "--generate-notes",
 696	        ];
 697	        let created = self.runner.run("gh", &create_args, &self.prepared.root)?;
 698	        if created.exit_code != Some(0) {
 699	            return Err(GraphError::ReleaseCommand {
 700	                program: "gh".to_string(),
 701	                args: create_args.iter().map(ToString::to_string).collect(),
 702	                failure: CommandFailure::NonZeroExit {
 703	                    exit_code: created.exit_code,
 704	                    stderr: created.stderr,
 705	                },
 706	            });
 707	        }
 708	        if self.observed_forge_release_target(tag, &repository)? == ForgeReleaseObservation::Exact {
 709	            Ok(OperationOutcome::Published)
 710	        } else {
 711	            Err(GraphError::ReleaseRemoteConflict {
 712	                conflict: RemoteConflict::ForgeReleaseNotObservedAfterCreate,
