 717	    fn observed_tag(&self, name: &TagName) -> Result<Option<ObservedTag>, GraphError> {
 718	        let reference = format!("refs/tags/{name}^{{commit}}");
 719	        let rev_parse_args = ["rev-parse", "--verify", "--quiet", reference.as_str()];
 720	        let observed = self.runner.run("git", &rev_parse_args, &self.prepared.root)?;
 721	        if observed.exit_code != Some(0) {
 722	            return Ok(None);
 723	        }
 724	        let target = CommitSha::parse(observed.stdout.trim()).map_err(|error| GraphError::ReleaseCommand {
 725	            program: "git".to_string(),
 726	            args: rev_parse_args.iter().map(ToString::to_string).collect(),
 727	            failure: CommandFailure::MalformedOutput {
 728	                detail: error.to_string(),
 729	            },
 730	        })?;
 731	        let for_each_ref_target = format!("refs/tags/{name}");
 732	        let for_each_ref_args = [
 733	            "for-each-ref",
 734	            "--format=%(objecttype)%00%(contents:subject)%00%(contents:body)",
 735	            for_each_ref_target.as_str(),
 736	        ];
 737	        let details = self.runner.run("git", &for_each_ref_args, &self.prepared.root)?;
 738	        if details.exit_code != Some(0) {
 739	            return Err(GraphError::ReleaseCommand {
 740	                program: "git".to_string(),
 741	                args: for_each_ref_args.iter().map(ToString::to_string).collect(),
 742	                failure: CommandFailure::NonZeroExit {
 743	                    exit_code: details.exit_code,
 744	                    stderr: details.stderr,
 745	                },
 746	            });
 747	        }
 748	        let line = details.stdout.trim_end_matches(['\r', '\n']);
 749	        let mut fields = line.split('\0');
 750	        let object_type = fields.next();
 751	        let annotation = fields.next();
 752	        let body = fields.next();
 753	        if object_type != Some("tag") || body.is_none_or(|body| !body.trim().is_empty()) || fields.next().is_some() {
 754	            return Err(GraphError::ReleaseCommand {
 755	                program: "git".to_string(),
 756	                args: for_each_ref_args.iter().map(ToString::to_string).collect(),
 757	                failure: CommandFailure::MalformedOutput {
 758	                    detail: format!("unexpected for-each-ref output: {line:?}"),
 759	                },
 760	            });
 761	        }
 762	        let annotation = annotation.ok_or_else(|| GraphError::ReleaseInvariant {
 763	            detail: "for-each-ref line validated as `tag`/empty-body but carried no annotation field".to_string(),
 764	        })?;
 765	        Ok(Some(ObservedTag {
 766	            target,
 767	            annotation: annotation.to_string(),
 768	        }))
 769	    }
