 771	    fn observed_forge_release_target(
 772	        &self,
 773	        tag: &TagName,
 774	        repository: &str,
 775	    ) -> Result<ForgeReleaseObservation, GraphError> {
 776	        let endpoint = format!("repos/{repository}/releases/tags/{tag}");
 777	        let api_args = [
 778	            "api",
 779	            "--include",
 780	            "--method",
 781	            "GET",
 782	            endpoint.as_str(),
 783	            "--repo",
 784	            repository,
 785	        ];
 786	        let observed = self.runner.run("gh", &api_args, &self.prepared.root)?;
 787	        if observed.exit_code != Some(0) {
 788	            return Err(GraphError::ReleaseCommand {
 789	                program: "gh".to_string(),
 790	                args: api_args.iter().map(ToString::to_string).collect(),
 791	                failure: CommandFailure::NonZeroExit {
 792	                    exit_code: observed.exit_code,
 793	                    stderr: observed.stderr,
 794	                },
 795	            });
 796	        }
 797	        let (status, body) = parse_github_api_response("gh", &api_args, &observed.stdout)?;
 798	        if status == 404 {
 799	            return Ok(ForgeReleaseObservation::Missing);
 800	        }
 801	        if status != 200 {
 802	            return Err(GraphError::ReleaseRemoteConflict {
 803	                conflict: RemoteConflict::ForgeApiStatus,
 804	            });
 805	        }
 806	        let value: serde_json::Value = serde_json::from_str(body).map_err(|error| GraphError::ReleaseCommand {
 807	            program: "gh".to_string(),
 808	            args: api_args.iter().map(ToString::to_string).collect(),
 809	            failure: CommandFailure::MalformedOutput {
 810	                detail: error.to_string(),
 811	            },
 812	        })?;
 813	        let expected = match &self.prepared.source {
 814	            SourceIdentity::GitCommit { sha } => sha.as_str(),
 815	            SourceIdentity::HermeticContent { .. } => {
 816	                return Err(GraphError::UnsupportedRelease {
 817	                    feature: UnsupportedReleaseFeature::SourceIdentity,
 818	                })
 819	            }
 820	        };
 821	        Ok(
 822	            if value.get("tag_name").and_then(serde_json::Value::as_str) == Some(tag.as_str())
 823	                && value.get("target_commitish").and_then(serde_json::Value::as_str) == Some(expected)
 824	            {
 825	                ForgeReleaseObservation::Exact
 826	            } else {
 827	                ForgeReleaseObservation::Conflict
 828	            },
 829	        )
 830	    }
