 338	impl ValidatedReleaseIntent<'_> {
 339	    /// Dispatches exactly one graph-private operation prepared during fresh
 340	    /// validation. This is intentionally the only production effect path: it
 341	    /// never accepts a path, endpoint, tag, package name, or version from a
 342	    /// caller.
 343	    pub(crate) fn dispatch_prepared(
 344	        &self,
 345	        permit: &ApplyPermit,
 346	        id: &ReleaseOperationId,
 347	    ) -> Result<OperationOutcome, GraphError> {
 348	        let operation = self
 349	            .prepared
 350	            .operations
 351	            .get(id)
 352	            .ok_or_else(|| GraphError::ReleaseInvariant {
 353	                detail: format!("dispatch_prepared: no prepared operation for `{id:?}`"),
 354	            })?;
 355	        match operation {
 356	            PreparedOperation::RegistryPublish { .. } => self.dispatch_registry(permit, id, operation),
 357	            PreparedOperation::Tag {
 358	                name,
 359	                target,
 360	                annotation,
 361	            } => self.dispatch_tag(permit, name, target, annotation),
 362	            PreparedOperation::ForgeRelease { tag } => self.dispatch_forge_release(tag),
 363	        }
 364	    }
 365	
 366	    fn dispatch_registry(
 367	        &self,
 368	        _permit: &ApplyPermit,
 369	        id: &ReleaseOperationId,
 370	        prepared: &PreparedOperation,
 371	    ) -> Result<OperationOutcome, GraphError> {
 372	        let PreparedOperation::RegistryPublish {
 373	            package_dir,
 374	            package_name,
 375	            version,
 376	            registry,
 377	            npm_access,
 378	            npm_tag,
 379	        } = prepared
 380	        else {
 381	            return Err(GraphError::ReleaseInvariant {
 382	                detail: format!("dispatch_registry: operation `{id:?}` is not a RegistryPublish"),
 383	            });
 384	        };
 385	        let output = match id.package.ecosystem() {
 386	            Ecosystem::Cargo => {
 387	                let registry_key = (registry.key.as_str() != RegistryKey::CRATES_IO).then(|| registry.key.as_str());
 388	                let argv = registry_argv::cargo_publish_argv(
 389	                    &self.prepared.root,
 390	                    package_dir,
 391	                    package_name,
 392	                    version,
 393	                    registry_key,
 394	                )?;
 395	                self.run_argv(&argv)?
 396	            }
 397	            Ecosystem::Npm => {
 398	                if self.npm_version_is_published(package_name, version, registry.endpoint.as_deref())? {
 399	                    return Ok(OperationOutcome::AlreadySatisfied);
 400	                }
 401	                let package_manager = registry_argv::detect_npm_package_manager(&self.prepared.root);
 402	                let argv = registry_argv::npm_publish_argv(
 403	                    &self.prepared.root,
 404	                    package_dir,
 405	                    package_name,
 406	                    package_manager,
 407	                    npm_tag.as_deref(),
 408	                    *npm_access,
 409	                    registry.endpoint.as_deref(),
 410	                );
 411	                self.run_argv(&argv)?
 412	            }
 413	            Ecosystem::Pypi => {
 414	                let steps = registry_argv::pypi_publish_argv(
 415	                    &self.prepared.root,
 416	                    package_dir,
 417	                    package_name,
 418	                    version,
 419	                    registry.endpoint.as_deref(),
 420	                );
 421	                let [build, upload] = steps.as_slice() else {
 422	                    return Err(GraphError::ReleaseInvariant {
 423	                        detail: "pypi_publish_argv did not return exactly a build and an upload step".to_string(),
 424	                    });
 425	                };
 426	                let built = self.run_argv(build)?;
 427	                if built.exit_code != Some(0) {
 428	                    return Err(GraphError::ReleaseCommand {
 429	                        program: build.program.clone(),
 430	                        args: build.args.clone(),
 431	                        failure: CommandFailure::NonZeroExit {
 432	                            exit_code: built.exit_code,
 433	                            stderr: built.stderr,
 434	                        },
 435	                    });
 436	                }
 437	                self.run_argv(upload)?
 438	            }
 439	            _ => {
 440	                return Err(GraphError::UnsupportedRelease {
 441	                    feature: UnsupportedReleaseFeature::Ecosystem,
 442	                })
 443	            }
 444	        };
 445	        let outcome = match id.package.ecosystem() {
 446	            Ecosystem::Cargo => registry_argv::classify_cargo_output(&output),
 447	            Ecosystem::Npm => registry_argv::classify_npm_publish_output(&output),
 448	            Ecosystem::Pypi => registry_argv::classify_twine_output(&output),
 449	            _ => {
 450	                return Err(GraphError::UnsupportedRelease {
 451	                    feature: UnsupportedReleaseFeature::Ecosystem,
 452	                })
 453	            }
 454	        }
 455	        .map_err(|source| GraphError::Registry {
 456	            package: package_name.clone(),
 457	            source,
 458	        })?;
 459	        if matches!(outcome, PublishOutcome::Published)
 460	            && ecosystem_requires_registry_confirmation(id.package.ecosystem())
 461	        {
 462	            let is_published = match id.package.ecosystem() {
 463	                Ecosystem::Npm => poll_until_published(
 464	                    || self.npm_version_is_published(package_name, version, registry.endpoint.as_deref()),
 465	                    REGISTRY_CONFIRMATION_MAX_RETRIES,
 466	                    registry_confirmation_backoff,
 467	                    std::thread::sleep,
 468	                )?,
 469	                Ecosystem::Cargo => {
 470	                    let registry_key = (registry.key.as_str() != RegistryKey::CRATES_IO).then(|| registry.key.as_str());
 471	                    poll_until_published(
 472	                        || self.cargo_version_is_published(package_name, version, registry_key),
 473	                        REGISTRY_CONFIRMATION_MAX_RETRIES,
 474	                        registry_confirmation_backoff,
 475	                        std::thread::sleep,
 476	                    )?
 477	                }
 478	                other => {
 479	                    return Err(GraphError::ReleaseInvariant {
 480	                        detail: format!(
 481	                            "ecosystem_requires_registry_confirmation returned true for {other:?}, which has no confirmation check wired"
 482	                        ),
 483	                    })
 484	                }
 485	            };
 486	            require_registry_confirmation(is_published, package_name, version)?;
 487	        }
 488	        Ok(match outcome {
 489	            PublishOutcome::Published => OperationOutcome::Published,
 490	            PublishOutcome::AlreadyPublished => OperationOutcome::AlreadySatisfied,
 491	        })
 492	    }
 493	}
