 550	impl ValidatedReleaseIntent<'_> {
 551	    /// Runs a [`registry_argv::Argv`] built by the pure argv layer. This is
 552	    /// the only place `dispatch_registry` touches [`CommandRunner`] --
 553	    /// everything about *what* to run (program, args, cwd) was already
 554	    /// decided by `registry_argv`.
 555	    fn run_argv(&self, argv: &registry_argv::Argv) -> Result<CommandOutput, GraphError> {
 556	        let args: Vec<&str> = argv.args.iter().map(String::as_str).collect();
 557	        Ok(self.runner.run(&argv.program, &args, &argv.cwd)?)
 558	    }
 559	
 560	    fn npm_version_is_published(
 561	        &self,
 562	        package_name: &str,
 563	        version: &Version,
 564	        registry: Option<&str>,
 565	    ) -> Result<bool, GraphError> {
 566	        let spec = format!("{package_name}@{}", version.render());
 567	        let mut args = vec!["view", spec.as_str(), "--json"];
 568	        if let Some(registry) = registry {
 569	            args.extend(["--registry", registry]);
 570	        }
 571	        let output = self
 572	            .runner
 573	            .run_quiet("npm", &args, &self.prepared.root, std::time::Duration::from_secs(300))?;
 574	        if output.success() {
 575	            return Ok(!output.stdout_trimmed().is_empty());
 576	        }
 577	        let details = format!("{}\n{}", output.stdout, output.stderr).to_ascii_lowercase();
 578	        if details.contains("e404")
 579	            || details.contains("etarget")
 580	            || details.contains("no matching version")
 581	            || details.contains("is not in this registry")
 582	        {
 583	            return Ok(false);
 584	        }
 585	        Err(GraphError::ReleaseCommand {
 586	            program: "npm".to_string(),
 587	            args: args.iter().map(ToString::to_string).collect(),
 588	            failure: CommandFailure::NonZeroExit {
 589	                exit_code: output.exit_code,
 590	                stderr: output.stderr,
 591	            },
 592	        })
