 615	    fn dispatch_tag(
 616	        &self,
 617	        permit: &ApplyPermit,
 618	        name: &TagName,
 619	        target: &CommitSha,
 620	        annotation: &str,
 621	    ) -> Result<OperationOutcome, GraphError> {
 622	        if let Some(observed) = self.observed_tag(name)? {
 623	            return if observed.target == *target && observed.annotation == annotation {
 624	                Ok(OperationOutcome::AlreadySatisfied)
 625	            } else {
 626	                Err(GraphError::ReleaseRemoteConflict {
 627	                    conflict: RemoteConflict::TagTargetDiffers,
 628	                })
 629	            };
 630	        }
 631	        // Delegates to `GitAccess::create_tag` rather than inlining `git
 632	        // tag` argv, so this inherits its `--` end-of-options separator
 633	        // (defends `name` against being misread as a flag) on top of the
 634	        // `--no-sign` this durable path has always needed (this repo's CI
 635	        // sets `tag.gpgSign`/`commit.gpgsign` globally in some contexts,
 636	        // with no tag-signing key available here).
 637	        let git = GitAccess::discover(&self.prepared.root, self.runner);
 638	        git.create_tag(
 639	            name.as_str(),
 640	            target,
 641	            Some(annotation),
 642	            TagSignPolicy::ForceUnsigned,
 643	            permit,
 644	        )?;
 645	        let remote_endpoint = self.checked_git_remote()?.endpoint.clone();
 646	        let push_args = ["push", remote_endpoint.as_str(), name.as_str()];
 647	        let pushed = self.runner.run("git", &push_args, &self.prepared.root)?;
 648	        if pushed.exit_code != Some(0) {
 649	            return Err(GraphError::ReleaseCommand {
 650	                program: "git".to_string(),
 651	                args: push_args.iter().map(ToString::to_string).collect(),
 652	                failure: CommandFailure::NonZeroExit {
 653	                    exit_code: pushed.exit_code,
 654	                    stderr: pushed.stderr,
 655	                },
 656	            });
 657	        }
 658	        if self
 659	            .observed_tag(name)?
 660	            .is_some_and(|observed| observed.target == *target && observed.annotation == annotation)
 661	        {
 662	            Ok(OperationOutcome::Published)
 663	        } else {
 664	            Err(GraphError::ReleaseRemoteConflict {
 665	                conflict: RemoteConflict::TagNotObservedAfterPush,
 666	            })
 667	        }
 668	    }
