    34	/// Executes a release after requiring the exact artifact manifest whenever
    35	/// the intent declares compiled-binary slots.
    36	pub fn execute_release_with_artifacts<W: ReleaseStateWriter>(
    37	    capability: &ValidatedReleaseIntent<'_>,
    38	    store: &ReleaseStateStore<W>,
    39	    permit: &ApplyPermit,
    40	    artifacts: Option<&ArtifactManifestV1>,
    41	) -> Result<ReleaseExecutionStateV1, GraphError> {
    42	    let intent = capability.intent();
    43	    require_artifact_manifest_matches_intent(intent, artifacts)?;
    44	    let mut state = store.load_or_initialize(intent, permit)?;
    45	    loop {
