    55	        let outcome = capability.dispatch_prepared(permit, &operation)?;
    56	        state
    57	            .mark_terminal(&operation, outcome)
    58	            .map_err(|source| GraphError::ReleaseExecutionState { source })?;
    59	        store.save(intent, &state, permit)?;
    60	    }
