    99	/// Reconciles `state` against exactly `intent` without performing any I/O.
   100	///
   101	/// An operation is eligible only while it is `Pending` and every *transitive*
   102	/// prerequisite is exactly `Published` or `AlreadySatisfied`. `Attempting`,
   103	/// missing, failed, and blocked operations are never inferred as success.
   104	pub fn reconcile_release_execution(
   105	    intent: &ReleaseIntentV1,
   106	    state: &ReleaseExecutionStateV1,
   107	) -> Result<ReconciledReleaseExecution, GraphError> {
   108	    state
   109	        .validate_for_intent(intent)
   110	        .map_err(|source| GraphError::ReleaseExecutionState { source })?;
   111	
   112	    let prerequisites: BTreeMap<_, _> = intent
   113	        .operations
   114	        .iter()
   115	        .map(|operation| (operation.id().clone(), operation.prerequisites().to_vec()))
   116	        .collect();
   117	
   118	    let mut eligible = Vec::new();
   119	    for operation in &intent.operations {
   120	        if state.operation_state(operation.id()) != Some(OperationState::Pending) {
   121	            continue;
   122	        }
   123	        let mut visited = BTreeSet::new();
   124	        if prerequisites_satisfied_transitively(operation.id(), &prerequisites, state, &mut visited) {
   125	            eligible.push(operation.id().clone());
   126	        }
   127	    }
   128	    Ok(ReconciledReleaseExecution { eligible })
   129	}
