   788	            return Err(GraphError::ReleaseCommand {
   789	                program: "gh".to_string(),
   790	                args: api_args.iter().map(ToString::to_string).collect(),
   791	                failure: CommandFailure::NonZeroExit {
   792	                    exit_code: observed.exit_code,
   793	                    stderr: observed.stderr,
   794	                },
   795	            });
   796	        }
