   822	            if value.get("tag_name").and_then(serde_json::Value::as_str) == Some(tag.as_str())
   823	                && value.get("target_commitish").and_then(serde_json::Value::as_str) == Some(expected)
   824	            {
   825	                ForgeReleaseObservation::Exact
   826	            } else {
   827	                ForgeReleaseObservation::Conflict
