    40	fn plan(args: ReleasePlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    41	    if global.dry_run {
    42	        return Err(CliError::Other(
    43	            "release plan needs an output file; remove --dry-run because planning is already read-only".to_string(),
    44	        ));
    45	    }
    46	    let runner = CliCommandRunner;
    47	    let workspace = load_workspace(global, &runner)?;
    48	    let decision = match args.from_release_commit.as_deref() {
    49	        Some(raw) => {
    50	            let commit = callisto_model::CommitSha::parse(raw)
    51	                .map_err(|error| CliError::Other(format!("invalid merged release commit `{raw}`: {error}")))?;
    52	            let decision_path = args
    53	                .decision
    54	                .as_deref()
    55	                .expect("clap requires --decision alongside --from-release-commit");
    56	            derive_release_commit_decision(&workspace, &commit, decision_path)?
    57	        }
    58	        None => {
    59	            let selections = args
    60	                .packages
    61	                .iter()
    62	                .map(|raw| {
    63	                    ReleasePackageId::parse(raw).map_err(|error| {
    64	                        CliError::Other(format!(
    65	                            "invalid release package `{raw}`: {error}; use an exact ecosystem-qualified identity such as cargo/callisto-cli"
    66	                        ))
    67	                    })
    68	                })
    69	                .collect::<Result<Vec<_>, _>>()?;
    70	            let inference = select_inference();
    71	            let version_plan =
    72	                callisto_graph::commands::plan_version(&workspace, &inference, &VersionOptions::default())?;
    73	            derive_selected_release_decision(&workspace, &version_plan, &selections)?
    74	        }
    75	    };
    76	    let locator = IgnoreWalkLocator::new(&workspace.root);
    77	    let intent = build_release_intent(
    78	        &workspace.root,
    79	        &locator,
    80	        &runner,
    81	        &decision,
    82	        ExecutionTrustProfileV1::GitCommit,
    83	    )?;
    84	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run)
    85	        .expect("release plan rejects --dry-run before creating its explicit output");
    86	    write_intent(&args.out, &intent, &permit)?;
    87	    match global.format {
    88	        OutputFormat::Json => write_json(&mut std::io::stdout(), &intent)?,
    89	        OutputFormat::Text => println!("Wrote release intent {} to {}", intent.digest(), args.out.display()),
    90	    }
    91	    Ok(ExitCode::SUCCESS)
    92	}
